// Package store is the only package that talks to PostgreSQL. It runs the
// queries generated by sqlc inside transactions and translates database errors
// into the domain errors defined in package ledger.
package store

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"time"

	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/radadev/ledgerd/internal/ledger"
	"github.com/radadev/ledgerd/internal/store/db"
)

// PostgreSQL SQLSTATE codes the store reacts to.
const (
	sqlStateSerializationFailure = "40001"
	sqlStateDeadlockDetected     = "40P01"
	sqlStateLockNotAvailable     = "55P03" // raised when lock_timeout expires
	sqlStateUniqueViolation      = "23505"
)

// Defaults for Config.
const (
	DefaultLockTimeout = 3 * time.Second
	DefaultMaxAttempts = 4 // the first try plus three retries
	DefaultBackoffBase = 10 * time.Millisecond
	maxBackoff         = 500 * time.Millisecond
)

// Config tunes transaction handling. Zero values select the defaults.
type Config struct {
	// LockTimeout bounds how long a statement waits for a row lock.
	LockTimeout time.Duration
	// MaxAttempts is the total number of tries for a transaction that is
	// aborted by a deadlock or serialization failure.
	MaxAttempts int
	// BackoffBase is the delay before the first retry; it doubles each time.
	BackoffBase time.Duration
}

func (c Config) withDefaults() Config {
	if c.LockTimeout <= 0 {
		c.LockTimeout = DefaultLockTimeout
	}
	if c.MaxAttempts <= 0 {
		c.MaxAttempts = DefaultMaxAttempts
	}
	if c.BackoffBase <= 0 {
		c.BackoffBase = DefaultBackoffBase
	}
	return c
}

// Store gives access to the ledger tables.
type Store struct {
	pool *pgxpool.Pool
	cfg  Config

	// Replaced in tests so that retry behaviour can be checked without waiting.
	sleep func(ctx context.Context, d time.Duration) error
}

// New builds a Store on top of an existing connection pool.
func New(pool *pgxpool.Pool, cfg Config) *Store {
	return &Store{pool: pool, cfg: cfg.withDefaults(), sleep: sleepContext}
}

// Pool returns the underlying connection pool.
func (s *Store) Pool() *pgxpool.Pool { return s.pool }

// Queries returns query methods bound to the pool, for reads outside a
// transaction. Each call is its own implicit transaction.
func (s *Store) Queries() *db.Queries { return db.New(s.pool) }

// InTx runs fn inside a READ COMMITTED transaction.
//
//   - The transaction is committed if fn returns nil, otherwise rolled back.
//   - lock_timeout is set for the transaction, so a statement never waits
//     indefinitely for a row lock held by someone else. When it expires the
//     error is ledger.ErrTemporarilyUnavailable and nothing is retried here:
//     the caller decides whether to try again later.
//   - If PostgreSQL aborts the transaction because of a deadlock or a
//     serialization failure, the whole of fn is run again, up to
//     Config.MaxAttempts times, with exponential backoff and jitter. Because
//     fn may run more than once, it must not have effects outside the database
//     transaction. When the attempts run out the error is
//     ledger.ErrTemporarilyUnavailable.
func (s *Store) InTx(ctx context.Context, fn func(ctx context.Context, q *db.Queries) error) error {
	return s.retrying(ctx, func() error { return s.runOnce(ctx, fn) })
}

func (s *Store) runOnce(ctx context.Context, fn func(ctx context.Context, q *db.Queries) error) (err error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	// Rolling back after a successful commit is a harmless no-op.
	defer func() { _ = tx.Rollback(ctx) }()

	// set_config(..., true) is SET LOCAL: it lasts until the end of the transaction.
	if _, err := tx.Exec(ctx, `SELECT set_config('lock_timeout', $1, true)`,
		fmt.Sprintf("%dms", s.cfg.LockTimeout.Milliseconds())); err != nil {
		return fmt.Errorf("set lock_timeout: %w", err)
	}

	if err := fn(ctx, db.New(tx)); err != nil {
		return err
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

// retrying calls op and decides, from the error it returns, whether to run it
// again. It is separate from InTx so that the policy can be tested without a
// database.
func (s *Store) retrying(ctx context.Context, op func() error) error {
	for attempt := 1; ; attempt++ {
		err := op()
		if err == nil {
			return nil
		}

		switch sqlState(err) {
		case sqlStateSerializationFailure, sqlStateDeadlockDetected:
			if attempt >= s.cfg.MaxAttempts {
				return fmt.Errorf("%w: gave up after %d attempts: %w", ledger.ErrTemporarilyUnavailable, attempt, err)
			}
			if serr := s.sleep(ctx, s.backoff(attempt)); serr != nil {
				return serr
			}
		case sqlStateLockNotAvailable:
			return fmt.Errorf("%w: %w", ledger.ErrTemporarilyUnavailable, err)
		default:
			return err
		}
	}
}

// backoff returns the delay before retry number attempt (1-based): the base
// doubled each time, capped, plus up to 50% random jitter so that transactions
// that collided do not collide again in lockstep.
func (s *Store) backoff(attempt int) time.Duration {
	d := s.cfg.BackoffBase << (attempt - 1)
	if d <= 0 || d > maxBackoff {
		d = maxBackoff
	}
	//nolint:gosec // jitter does not need a cryptographically secure source
	return d + rand.N(d/2+1)
}

func sleepContext(ctx context.Context, d time.Duration) error {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-t.C:
		return nil
	}
}

// pgError returns the PostgreSQL error wrapped in err, if any.
func pgError(err error) *pgconn.PgError {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		return pgErr
	}
	return nil
}

// sqlState returns the SQLSTATE of the PostgreSQL error wrapped in err, or "".
func sqlState(err error) string {
	if pgErr := pgError(err); pgErr != nil {
		return pgErr.Code
	}
	return ""
}
